async function getUserProfile(userId: string): Promise<UserProfile | null> {
  const cacheKey = `user:profile:v1:${userId}`;
  const cached = await redis.get(cacheKey);

  if (cached !== null) {
    return cached === '__NULL__' ? null : JSON.parse(cached);
  }

  const user = await db.users.findUnique({ where: { id: userId } });
  if (!user) {
    // Cache sentinel with short 60s TTL to prevent DB penetration attacks
    await redis.set(cacheKey, '__NULL__', 'EX', 60);
    return null;
  }

  // Add randomized jitter (3600s + 0..300s) to avoid mass synchronized expiration
  const ttlSeconds = 3600 + Math.floor(Math.random() * 300);
  await redis.set(cacheKey, JSON.stringify(user), 'EX', ttlSeconds);
  return user;
}
